const fontes = [
  {
    nome: "Inter Miami - Notícias",
    url: "https://www.intermiamicf.com/news/",
    tipo: "noticias"
  },
  {
    nome: "Inter Miami - Tickets",
    url: "https://www.intermiamicf.com/tickets/",
    tipo: "ingressos"
  },
  {
    nome: "Inter Miami - Anúncio do Jogo",
    url: "https://www.intermiamicf.com/news/international-friendly-river-plate-vs-inter-miami-cf-at-estadio-monumental",
    tipo: "oficial"
  },
  {
    nome: "River Plate - Ingressos",
    url: "https://www.riverplate.com/tickets",
    tipo: "ingressos"
  },
  {
    nome: "River Plate - Como Comprar",
    url: "https://www.riverplate.com/tickets/how-to-buy-tickets",
    tipo: "informacoes"
  },
  {
    nome: "River Plate - Calendário",
    url: "https://www.riverplate.com/venta-de-entradas/calendario-de-partidos",
    tipo: "oficial"
  },
  {
    nome: "River Plate - Página Principal",
    url: "https://www.riverplate.com/",
    tipo: "noticias"
  }
];

return fontes.map(fonte => ({
  json: {
    ...fonte,
    jogo: "River Plate vs Inter Miami",
    palavrasChave: [
      "inter miami",
      "river plate",
      "entradas",
      "tickets",
      "venta de entradas",
      "venta general",
      "preventa",
      "entradas disponibles",
      "tickets on sale",
      "comprar"
    ]
  }
}));

const items = $input.all();

const resultados = items.map((item, index) => {
  const texto = String(item.json.texto || "");
  const textoNormalizado = texto.toLowerCase();

  const mencionaRiver =
    /river plate/i.test(textoNormalizado);

  const mencionaMiami =
    /inter miami/i.test(textoNormalizado);

  const palavrasVenda = [
    "venta de entradas",
    "entradas disponibles",
    "tickets on sale",
    "tickets available",
    "venta general",
    "comprar entradas",
    "buy tickets"
  ];

  const termosEncontrados = palavrasVenda.filter(
    termo => textoNormalizado.includes(termo)
  );

  return {
    json: {
      fonte: index + 1,
      jogoEncontrado: mencionaRiver && mencionaMiami,
      indiciosVenda: termosEncontrados,
      possivelVenda: (
        mencionaRiver &&
        mencionaMiami &&
        termosEncontrados.length > 0
      ),
      trecho: texto.slice(0, 1000)
    }
  };
});

return resultados;

